void unregister_ppp_channel(struct ppp_channel *chan) {
    if (!chan)
        return;

    chan->file->private_data = NULL;
    write_lock_bh(&chan->lock);
    ppp_disestablish(chan);
    list_del(&chan->list);
    write_unlock_bh(&chan->lock);

    if (atomic_dec_and_test(&chan->file->f_count)) {
        fput(chan->file);
        kfree(chan);
    }

    wake_up_all(&chan->file->wait);
}

void unregister_ppp_channel(struct ppp_channel *chan) {
    if (!chan)
        return;

    chan->ppp = NULL;

    if (chan->file) {
        write_lock_bh(&chan->file->rlock);
        ppp_disconnect(chan);
        list_del(&chan->list);
        fput(chan->file);
        if (!--chan->file->f_count)
            ppp_destroy_channel(chan);
        wake_up_all(&chan->file->wq);
    }
}

